get isInDST() {
  if (this.isOffsetFixed) {
    return false;
  } else {
    // the standard offset is the smaller of the offsets at the beginning of the
    // year and in the middle of it; this works for both hemispheres
    const stdOffset = Math.min(
      this.set({ month: 1, day: 1 }).offset,
      this.set({ month: 5, day: 1 }).offset
    );

    // some years have unusual DST schedules (e.g. the US in 1974, when DST ran from
    // January 6 to October 27), so check the whole local day, not just this instant
    return (
      this.offset > stdOffset ||
      this.startOf("day").offset > stdOffset ||
      this.endOf("day").offset > stdOffset
    );
  }
}

